    'Crawl checked 2026-10-19: 28 candidates on 2 listing pages, dated ' || '[added by Claude 2026-10-19, Build #101 Vaterland crawl]', 'vaterland.li', 'html', 'approved', now(), now())
  RETURNING id INTO sid;
  INSERT INTO publishers (country_id, name, homepage_url, feed_status, language, domain, source_type)
  VALUES (li, 'Liechtensteiner Vaterland', 'https://www.vaterland.li/', 'active', 'de', 'vaterland.li', 'NEWSPAPER') RETURNING id INTO pid;
  INSERT INTO feeds (publisher_id, feed_url, feed_type, crawl_frequency_minutes, enabled, respect_robots_txt,
                     allowed_domains, category_urls, article_url_patterns, parser_config)
  VALUES (pid, 'https://www.vaterland.li/', 'html', 30, true, true, ARRAY['vaterland.li']::text[], ARRAY['https://www.vaterland.li/liechtenstein/']::text[], ARRAY['/liechtenstein/*/*-art-*']::text[], '{"title_suffix": " (Abo)"}'::jsonb);
  UPDATE publisher_submissions SET publisher_id = pid WHERE id = sid;
  INSERT INTO editorial_profiles (publisher_id, ownership_type, owner, classification_tags, political_party_association, historical_context,
    current_context, confidence, evidence_summary, evidence_sources, classification_date, last_reviewed, evidence_date, review_required)
  VALUES (pid, $$Entreprise de presse privée$$, $$Vaduzer Medienhaus AG$$, ARRAY['party_aligned']::text[], $$Vaterländische Union (VU)$$, $$Quotidien fondé le 1er janvier 1936, organe officiel de l'Union patriotique (Vaterländische Union). Depuis la fermeture du Liechtensteiner Volksblatt en mars 2023, seul quotidien imprimé du pays ; les abonnés du Volksblatt lui ont été transférés.$$, $$Le journal a annoncé vouloir évoluer vers une ligne politiquement neutre, mais son éditeur, Vaduzer Medienhaus AG, reste proche de l'Union patriotique. Une partie des articles est réservée aux abonnés (« Abo ») ; titres et chapôs restent publics.$$, 'high',
